  (* [comment removed for export] *)
  Lemma z4e_blocks : AIMG_HI <= DT /\ DT + DTL <= ATOP /\ DT mod 16 = 0 /\ DT + 4 + zlen cbs <= DT + DTL
                     /\ (dcap = 0 \/ (AIMG_HI <= DST /\ DST + dcap <= ATOP))
